<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {useRouter} from 'vue-router'
import {session,logout,clearSession,ApiError} from '../auth'
const applied=ref<{games:string,trades:string}|null>(null)
const router=useRouter(),menuOpen=ref(false),sport=ref(''),start=ref(''),end=ref(''),wallet=ref(''),kind=ref(''),gameStatus=ref(''),tradeState=ref(''),wallets=ref<any[]>([]),games=ref<any[]>([]),trades=ref<any[]>([]),statistics=ref<any>(null),gameCursor=ref<string|null>(null),tradeCursor=ref<string|null>(null),message=ref(''),loading=ref(false),loaded=ref(false)
async function api(path:string){const response=await fetch('/api/v1'+path,{credentials:'same-origin',cache:'no-store'});const body=await response.json();if(!response.ok)throw new Error(body?.error?.message||'请求失败');return body.data}
function params(target:'games'|'trades'|'statistics'){const p=new URLSearchParams();if(sport.value)p.set('sport',sport.value);if(start.value)p.set('from',new Date(start.value+'T00:00:00+08:00').toISOString());if(end.value)p.set('to',new Date(end.value+'T00:00:00+08:00').toISOString());if(target!=='trades'&&gameStatus.value)p.set('status',gameStatus.value);if(target!=='games'){if(wallet.value)p.set('wallet_id',wallet.value);if(kind.value)p.set('kind',kind.value);if(tradeState.value)p.set('state',tradeState.value)}return p}
async function load(){loading.value=true;message.value='';try{const snapshot={games:params('games').toString(),trades:params('trades').toString()};const [g,t,s]=await Promise.all([api('/history/games?'+snapshot.games),api('/history/trades?'+snapshot.trades),api('/statistics?'+params('statistics'))]);applied.value=snapshot;games.value=g.items;trades.value=t.items;gameCursor.value=g.next_cursor;tradeCursor.value=t.next_cursor;statistics.value=s;loaded.value=true}catch(e){message.value=e instanceof Error?e.message:'历史数据加载失败。'}finally{loading.value=false}}
async function more(target:'games'|'trades'){const p=new URLSearchParams(applied.value?.[target]||''),cursor=target==='games'?gameCursor.value:tradeCursor.value;if(!cursor)return;p.set('cursor',cursor);try{const data=await api('/history/'+target+'?'+p);if(target==='games'){games.value.push(...data.items);gameCursor.value=data.next_cursor}else{trades.value.push(...data.items);tradeCursor.value=data.next_cursor}}catch{message.value='加载更多失败，请重试。'}}
async function download(target:'games'|'trades',format:'csv'|'xlsx'){try{const response=await fetch('/api/v1/exports/'+target+'.'+format+'?'+(applied.value?.[target]||''),{credentials:'same-origin',cache:'no-store'});if(!response.ok)throw new Error('导出失败，请检查筛选或登录状态。');const blob=await response.blob();const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='polysports-'+target+'.'+format;link.click();URL.revokeObjectURL(link.href)}catch(e){message.value=e instanceof Error?e.message:'导出失败。'}}
async function signOut(){try{await logout();await router.replace('/login')}catch(e){if(e instanceof ApiError&&e.status===401){clearSession();await router.replace('/login')}else message.value='退出请求未确认，请重试。'}}
onMounted(async()=>{try{wallets.value=(await api('/wallets')).items}catch{message.value='钱包列表不可用。'}await load()})
</script>
<template><div class="app-layout"><header class="mobile-header"><div class="brand">PolySports</div><button class="menu-button" :aria-expanded="menuOpen" aria-controls="primary-nav" @click="menuOpen=!menuOpen">菜单</button></header><aside id="primary-nav" class="sidebar" :class="{open:menuOpen}"><div class="brand sidebar-brand">PolySports</div><nav aria-label="主导航"><RouterLink to="/">总览</RouterLink><RouterLink to="/sports/football">足球赛事</RouterLink><RouterLink to="/sports/nba">NBA 赛事</RouterLink><RouterLink to="/combos">组合交易</RouterLink><RouterLink to="/orders">交易记录</RouterLink><RouterLink to="/history">历史与导出</RouterLink><RouterLink to="/wallets">钱包状态</RouterLink><RouterLink to="/system">系统管理</RouterLink></nav></aside><main class="workspace combo-page"><div class="workspace-top"><span>工作台 / 历史与导出</span><div class="account"><span>{{session.username}}</span><button class="text-button" @click="signOut">退出</button></div></div><h1>历史与导出</h1><p>按 UTC+8 日期筛选；结束日期不含当天。导出包含最近一次应用筛选后的全部记录。</p><section class="welcome-card"><form @submit.prevent="load"><label>运动 <select v-model="sport"><option value="">全部</option><option value="football">足球</option><option value="nba">NBA</option></select></label><label>开始日期 <input v-model="start" type="date"></label><label>结束日期（不含） <input v-model="end" type="date"></label><label>赛事状态 <input v-model="gameStatus" placeholder="全部"></label><label>钱包 <select v-model="wallet"><option value="">全部</option><option v-for="w in wallets" :key="w.id" :value="w.id">{{w.label}}</option></select></label><label>交易类型 <select v-model="kind"><option value="">全部</option><option value="single">单场</option><option value="combo">组合</option></select></label><label>交易状态 <input v-model="tradeState" placeholder="全部"></label><button class="text-button" :disabled="loading">应用筛选</button></form></section><p role="status" class="form-message">{{message}}</p><p v-if="loading">正在加载历史记录…</p><section v-if="statistics" class="welcome-card"><h2>统计</h2><p>赛事 {{statistics.games_total}} · 完赛 {{statistics.finished_total}} · 交易意图 {{statistics.trade_count}}</p><p>已确认单场成交记录 {{statistics.confirmed_fill_count}} · 已确认组合 {{statistics.confirmed_combo_count}} · 已实现收益：{{statistics.realized_pnl ?? '未知'}}</p><p>{{statistics.scope}}</p></section><section class="welcome-card"><h2>历史赛事</h2><button class="text-button" @click="download('games','csv')">导出赛事 CSV</button><button class="text-button" @click="download('games','xlsx')">导出赛事 Excel</button><p v-if="loaded && !games.length">没有符合条件的赛事。</p><article v-for="game in games" :key="game.id" class="market-card"><p>{{game.home_team.name_zh || game.home_team.source_name}} 对 {{game.away_team.name_zh || game.away_team.source_name}} · {{game.status}}</p><p>{{new Date(game.starts_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}} UTC+8 · {{game.home_score ?? '未知'}} : {{game.away_score ?? '未知'}}</p></article><button v-if="gameCursor" class="text-button" @click="more('games')">加载更多赛事</button></section><section class="welcome-card"><h2>历史交易</h2><button class="text-button" @click="download('trades','csv')">导出交易 CSV</button><button class="text-button" @click="download('trades','xlsx')">导出交易 Excel</button><p v-if="loaded && !trades.length">没有符合条件的交易。</p><article v-for="trade in trades" :key="trade.kind+trade.id" class="market-card"><p>{{trade.kind==='single'?'单场':'组合'}} · {{trade.state}} · {{trade.side || trade.direction}}</p><p>创建：{{new Date(trade.created_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}} UTC+8 · 已实现收益：未知</p><RouterLink :to="trade.kind==='single'?'/orders':'/combos'">查看交易记录</RouterLink></article><button v-if="tradeCursor" class="text-button" @click="more('trades')">加载更多交易</button></section></main></div></template>
